import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
    const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

    // Root container for this UI element
    const root = new Group();

    // Geometry – maintain aspect ratio of the source image (512 × 320 → 1.6 : 1)
    const width = 1.6;
    const height = 1.0;
    const geometry = new PlaneGeometry(width, height);

    // Basic unlit material; texture will be applied once loaded
    const material = new MeshBasicNodeMaterial();
    material.color = new Color('#ffffff');

    const mesh = new Mesh(geometry, material);
    root.add(mesh);

    // Load texture asynchronously (function stays synchronous)
    let texture = null;
    if (config.imageUrl) {
        ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
            texture = tex;
            material.map = tex;
            material.needsUpdate = true;
        }).catch(() => {
            // fail silently – material stays white
        });
    }

    // Apply cinematic primitive(s)
    const primitiveHandles = [];
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const prim of config.cinematicPrimitives) {
            if (prim.name && ctx.primitives[prim.name]) {
                const handle = ctx.primitives[prim.name](root, prim.params || {});
                if (handle && typeof handle.cleanup === 'function') {
                    primitiveHandles.push(handle);
                }
            }
        }
    }

    // -----------------------------------------------------------------
    // Interaction handlers (hover lift & click emit)
    // -----------------------------------------------------------------
    const hoverAmount = 0.15; // scene units
    const hoverDuration = 0.3;
    const hoverEase = 'power3.out';
    const leaveDuration = 0.2;
    const leaveEase = 'power3.in';

    // Store original Y to avoid drift on repeated enters/leaves
    let originalY = root.position.y;

    const handlers = {
        hover: {
            enter: () => {
                originalY = root.position.y;
                gsap.to(root.position, {
                    y: originalY + hoverAmount,
                    duration: hoverDuration,
                    ease: hoverEase,
                });
            },
            leave: () => {
                gsap.to(root.position, {
                    y: originalY,
                    duration: leaveDuration,
                    ease: leaveEase,
                });
            },
        },
        click: () => {
            ctx.emit('hub-journal.select');
        },
    };

    root.userData.handlers = handlers;

    // -----------------------------------------------------------------
    // Cleanup routine
    // -----------------------------------------------------------------
    root.userData.cleanup = () => {
        // Dispose three.js resources
        geometry.dispose();
        material.dispose();
        if (texture) texture.dispose();

        // Kill GSAP tweens targeting this object's position
        gsap.killTweensOf(root.position);

        // Cleanup primitives
        for (const h of primitiveHandles) {
            if (typeof h.cleanup === 'function') {
                h.cleanup();
            }
        }
    };

    return root;
}
